  xs = x((s-1)*L+(1:L)); xs = xs-mean(xs);
  w = hann(L,'periodic'); X = abs(fft(xs.*w, L*8)); X = X(1:L*4+1); X(1:5)=0;
  fz = (0:L*4)'*fs/(L*8); [~,k]=max(X);
  fprintf('segment %d (%.2f-%.2f s): peak %.4f Hz\n', s, (s-1), s, fz(k));
end
